use std::io::{self, Write};

pub fn parse_n_arg<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let mut args = args.into_iter();
    let _program_name = args.next();

    match args.next() {
        Some(raw) => parse_stoi_i32(&raw),
        None => 11,
    }
}

fn parse_stoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let negative = match bytes.get(index) {
        Some(b'+') => {
            index += 1;
            false
        }
        Some(b'-') => {
            index += 1;
            true
        }
        _ => false,
    };

    let digits_start = index;
    let limit = if negative {
        -(i32::MIN as i64)
    } else {
        i32::MAX as i64
    };
    let mut magnitude = 0i64;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        let digit = (bytes[index] - b'0') as i64;
        if magnitude > (limit - digit) / 10 {
            abort_stoi("out_of_range");
        }
        magnitude = magnitude * 10 + digit;
        index += 1;
    }

    if index == digits_start {
        abort_stoi("invalid_argument");
    }

    if negative {
        -(magnitude as i64) as i32
    } else {
        magnitude as i32
    }
}

fn abort_stoi(kind: &str) -> ! {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of 'std::{}'",
        kind
    );
    let _ = writeln!(stderr, "  what():  stoi");
    let _ = stderr.flush();
    std::process::abort();
}

