use std::io::{self, Write};

use super::cli::parse_n_arg;
use super::vector::Vector;

pub fn run<I>(args: I)
where
    I: IntoIterator<Item = String>,
{
    let n = parse_n_arg(args);
    let (first_sum, second_sum) = compute_outputs(n);

    let mut stdout = io::stdout().lock();
    let _ = writeln!(stdout, "{}", first_sum);
    let _ = stdout.flush();
    let _ = writeln!(stdout, "{}", second_sum);
    let _ = stdout.flush();
}

fn compute_outputs(n: i32) -> (i32, i32) {
    let mut v = Vector::new();
    let mut i = 0i32;

    while i < n {
        v = v.push_back(i.wrapping_add(1));
        i = i.wrapping_add(1);
    }

    let mut sum = 0i32;
    for &x in v.iter() {
        sum = sum.wrapping_add(x);
    }
    let first_sum = sum;

    let mut v2 = Vector::new();
    let mut index = 0usize;
    while index < v.len() {
        v2 = v2.push_back(v[index].wrapping_mul(2));
        index += 1;
    }

    sum = 0;
    for &x in v2.iter() {
        sum = sum.wrapping_add(x);
    }

    (first_sum, sum)
}

